import { onRequestGet as verifyPurchase } from "./verify-purchase.js";
// Paid PDF is bundled server-side; no public static download URL is published.
const PDF_BASE64 = "";
export async function onRequestGet(context) {
  const verified = await verifyPurchase(context);
  if (!verified.ok) return verified;
  const purchase = await verified.json();
  if (purchase.bookSlug !== "home-battery-backup-budget-planner") {
    return new Response("This purchase does not include this book.", {status:403, headers:{"cache-control":"no-store"}});
  }
  const bytes = Uint8Array.from(atob(PDF_BASE64), c => c.charCodeAt(0));
  return new Response(bytes, {headers:{
    "content-type":"application/pdf",
    "content-disposition":'attachment; filename="home-battery-backup-budget-planner.pdf"',
    "cache-control":"private, no-store",
    "x-robots-tag":"noindex, nofollow",
    "referrer-policy":"no-referrer"
  }});
}
export async function onRequest() { return new Response("Method not allowed", {status:405}); }
